using System.Text.Json.Serialization;
namespace Wardogs.Scanner;

public sealed record StartRequest([property: JsonPropertyName("schema_version")] int SchemaVersion, [property: JsonPropertyName("scanner_version")] string ScannerVersion, [property: JsonPropertyName("build_sha256")] string BuildSha256);
public sealed record StartResponse([property: JsonPropertyName("incident_id")] string IncidentId, [property: JsonPropertyName("steam_id")] string SteamId, [property: JsonPropertyName("upload_token")] string UploadToken);
public sealed record ModuleResult([property: JsonPropertyName("name")] string Name, [property: JsonPropertyName("status")] string Status, [property: JsonPropertyName("started_at")] double StartedAt, [property: JsonPropertyName("ended_at")] double EndedAt, [property: JsonPropertyName("items_checked")] int ItemsChecked, [property: JsonPropertyName("error")] string Error);
public sealed record Evidence([property: JsonPropertyName("evidence_id")] string EvidenceId, [property: JsonPropertyName("type")] string Type, [property: JsonPropertyName("source")] string Source, [property: JsonPropertyName("timestamp")] double? Timestamp, [property: JsonPropertyName("timezone")] string Timezone, [property: JsonPropertyName("incident_relation")] string IncidentRelation, [property: JsonPropertyName("path")] string Path, [property: JsonPropertyName("sha256")] string Sha256, [property: JsonPropertyName("publisher")] string Publisher, [property: JsonPropertyName("signature")] string Signature, [property: JsonPropertyName("rule_id")] string RuleId, [property: JsonPropertyName("severity")] string Severity, [property: JsonPropertyName("confidence")] string Confidence, [property: JsonPropertyName("explanation")] string Explanation, [property: JsonPropertyName("details")] Dictionary<string, object?> Details);
public sealed record Consent([property: JsonPropertyName("accepted")] bool Accepted, [property: JsonPropertyName("modules")] string[] Modules);
public sealed record DeviceIdentity([property: JsonPropertyName("kind")] string Kind, [property: JsonPropertyName("digest")] string Digest);
public sealed record ScanReport([property: JsonPropertyName("schema_version")] int SchemaVersion, [property: JsonPropertyName("steam_id")] string SteamId, [property: JsonPropertyName("scanner_version")] string ScannerVersion, [property: JsonPropertyName("build_sha256")] string BuildSha256, [property: JsonPropertyName("scan_started_at")] double ScanStartedAt, [property: JsonPropertyName("scan_ended_at")] double ScanEndedAt, [property: JsonPropertyName("admin")] bool Admin, [property: JsonPropertyName("consent")] Consent Consent, [property: JsonPropertyName("modules")] List<ModuleResult> Modules, [property: JsonPropertyName("evidence")] List<Evidence> Evidence, [property: JsonPropertyName("errors")] List<string> Errors, [property: JsonPropertyName("device_identity")] DeviceIdentity? DeviceIdentity = null);
public sealed record SubmitResponse([property: JsonPropertyName("report_id")] string ReportId, [property: JsonPropertyName("status")] string Status);
